<script lang="ts">
 import { onMount } from 'svelte';
 import type { Analysis } from '../lib/types';
 import { echarts, palette } from '../lib/charts';
 import { theme } from '../lib/theme.svelte';
 import { volumeData } from '../lib/volume';
 import { formatTime } from '../lib/time';
 let { analysis, zone }: { analysis:Analysis; zone:string }=$props();
 let first=$state(0),last=$state(119),focus=$state(''),search=$state(''),page=$state(0);
 let node=$state<HTMLDivElement>(),chart=$state<ReturnType<typeof echarts.init>>();
 const data=$derived(volumeData(analysis.query,analysis.requestVolume??[],first,last,8,focus));
 const filtered=$derived(data.apis.filter(api=>(api.controller+'.'+api.action).toLowerCase().includes(search.toLowerCase())));
 const currentPage=$derived(Math.min(page,Math.max(0,Math.ceil(filtered.length/10)-1)));
const stamp=(at:number)=>formatTime(at,{zone,suffix:false});
 $effect(()=>{analysis;first=0;last=119;focus='';page=0;search='';});
 onMount(()=>{if(!node)return;chart=echarts.init(node);const observer=new ResizeObserver(()=>chart?.resize());observer.observe(node);chart.on('click',(event)=>{if(typeof event.dataIndex==='number'){const selected=data.first+event.dataIndex;first=selected;last=selected;page=0;}});return()=>{observer.disconnect();chart?.dispose();};});
 $effect(()=>{if(!chart)return;void theme.epoch;const p=palette(),axis={axisLine:{lineStyle:{color:p.axisLine}},axisLabel:{color:p.text2},nameTextStyle:{color:p.text2}};chart.setOption({animation:false,color:[...p.series,p.pending],textStyle:{color:p.text2},tooltip:{trigger:'axis',renderMode:'richText',confine:true},legend:{type:'scroll',top:0,textStyle:{fontSize:11,color:p.text2},pageTextStyle:{color:p.text2},formatter:(name:string)=>name.length>42?name.slice(0,39)+'…':name},grid:{left:65,right:20,top:65,bottom:65},xAxis:{type:'category',name:'Request start time',nameLocation:'middle',nameGap:42,data:data.slots.map(slot=>stamp(slot.start)),...axis,axisLabel:{color:p.text2,hideOverlap:true,fontSize:11}},yAxis:{type:'value',name:'Requests',minInterval:1,...axis,splitLine:{lineStyle:{color:p.grid}}},series:data.series.map(series=>({name:series.name,type:'bar',stack:'requests',emphasis:{focus:'series'},data:series.counts}))},true);});
</script>
<section class="data-section request-volume" aria-label="Request counts by API">
 <div class="section-heading"><div><h3>How many requests happened, and which APIs were they?</h3><p>Each bar is a time slice. Its height is the number of requests that started; its colors identify individual APIs.</p></div></div>
 <div class="volume-controls"><label>Window starts<select aria-label="Request volume window starts" value={data.first} onchange={(event)=>{first=Number(event.currentTarget.value);if(last<first)last=first;page=0;}}>{#each data.allSlots as slot,i}<option value={i}>{stamp(slot.start)}</option>{/each}</select></label><label>Window ends<select aria-label="Request volume window ends" value={data.last} onchange={(event)=>{last=Number(event.currentTarget.value);if(first>last)first=last;page=0;}}>{#each data.allSlots as slot,i}<option value={i}>{stamp(slot.end)}</option>{/each}</select></label><button class="secondary-button" onclick={()=>{first=0;last=119;focus='';page=0;}}>Full investigation window</button>{#if focus}<button class="secondary-button" onclick={()=>{focus='';page=0;}}>Show all APIs</button>{/if}</div>
 <p class="volume-summary"><strong>{data.total.toLocaleString()} requests · {data.apis.length.toLocaleString()} API names</strong>{#if data.slots.length}{' · '}{stamp(data.slots[0].start)}–{stamp(data.slots[data.slots.length-1].end)} ({zone}){/if}</p>
 <p class="activity-explanation">The eight busiest API names are colored separately; Other APIs includes every remaining name. Matching controller/action names are combined across selected sources, request types and outcomes. Counts include missing or unusable response timings and follow this comparison’s filters. This counts requests that started in the window, not ones already running. Click a bar to inspect that time slice, or use the window controls. Slice boundaries follow the comparison’s chart interval; changing them uses the current result.</p>
 {#if analysis.sources.some(source=>!source.ok)}<div class="inline-error" role="status">Some sources failed. These counts cover successful sources only; zero does not establish that no activity occurred in failed sources.</div>{/if}
 {#if analysis.requestVolume==null}<p class="sample-note">Run analysis again to load request counts for this result.</p>{:else if !data.total}<p class="sample-note">No matching request starts in this window. Choose a wider window or clear the selected API.</p>{/if}
 <div class="volume-chart" bind:this={node} role="img" aria-label={'Stacked request-count histogram: '+data.total+' requests across '+data.apis.length+' API names. Exact counts are listed below.'}></div>
 <div class="volume-table-heading"><h4>Exact counts in this window</h4><label>Find an API<input type="search" aria-label="Find an API in request counts" bind:value={search} oninput={()=>page=0} placeholder="Controller or action" /></label></div>
 <div class="volume-table-wrap"><table class="volume-table"><thead><tr><th scope="col">API name</th><th scope="col">Requests</th><th scope="col">Share</th><th scope="col">Chart</th></tr></thead><tbody>{#each filtered.slice(currentPage*10,currentPage*10+10) as api (api.key)}<tr><th scope="row">{api.controller||'(unnamed controller)'}.{api.action||'(unnamed action)'}</th><td>{api.total.toLocaleString()}</td><td>{data.total?(api.total/data.total*100).toFixed(1):'0'}%</td><td><button class="quiet-button" aria-label={'Show only '+api.controller+'.'+api.action+' in histogram'} onclick={()=>{focus=api.key;search='';page=0;}}>Show only</button></td></tr>{/each}</tbody></table></div>
 <div class="pagination-row"><span>{filtered.length.toLocaleString()} matching API names · page {currentPage+1} of {Math.max(1,Math.ceil(filtered.length/10))}</span><div><button class="secondary-button" disabled={currentPage===0} onclick={()=>page=currentPage-1}>Previous APIs</button><button class="secondary-button" disabled={(currentPage+1)*10>=filtered.length} onclick={()=>page=currentPage+1}>Next APIs</button></div></div>
</section>
